package com.iortatechnxt.finverse.reinsurance.domain;

/** Lifecycle of a statement of account. */
public enum SoaStatus {
  /** Generated by a maker; figures may still be regenerated. */
  PENDING_APPROVAL,
  /** Approved by a checker; statement adjustments accounted for. */
  APPROVED,
  /** Balance paid to or received from the reinsurer; open items matched. */
  SETTLED
}
